mapper.delete:
DELETE FROM ${tableName}
WHERE id IN (
    SELECT id FROM ai_document_chunk WHERE document_id = #{documentId}
)

DELETE FROM ${tableName}
WHERE id IN (
    SELECT id FROM ai_document_chunk WHERE kb_id = #{kbId}
)

mapper.select:
SELECT
    id,
    vector_id,
    content,
    metadata,
    (1 - (embedding <=> #{queryVector, typeHandler=com.lambda.fusion.ai.support.handler.PgVectorHandler})) as score,
    (embedding <=> #{queryVector, typeHandler=com.lambda.fusion.ai.support.handler.PgVectorHandler}) as distance
FROM ai_vector_store
WHERE kb_id = #{kbId}
  AND dimension = #{dimension}
  AND (1 - (embedding <=> #{queryVector, typeHandler=com.lambda.fusion.ai.support.handler.PgVectorHandler})) > #{minScore}
ORDER BY score DESC
LIMIT #{topK}
